spring: jackson: time-zone: UTC date-format: "yyyy-MM-dd HH:mm:ss" banner: charset: UTF-8 datasource: driver-class-name: {{ dolphin_database_config['dolphin_database_driver'] }} url: {{ dolphin_database_config['dolphin_database_url'] }} username: {{ dolphin_database_config['dolphin_database_username'] }} password: {{ dolphin_database_config['dolphin_database_password'] }} hikari: connection-test-query: select 1 minimum-idle: 5 auto-commit: true validation-timeout: 3000 pool-name: DolphinScheduler maximum-pool-size: 50 connection-timeout: 30000 idle-timeout: 600000 leak-detection-threshold: 0 initialization-fail-timeout: 1
server: port: {{ dolphin_alert_server_application_map['server.port'] }}
management: endpoints: web: exposure: include: health,metrics,prometheus endpoint: health: enabled: true show-details: always health: db: enabled: true defaults: enabled: false metrics: tags: application: ${spring.application.name}
alert: port: {{ dolphin_alert_server_application_map['alert.port'] }} # Mark each alert of alert server if late after x milliseconds as failed. # Define value is (0 = infinite), and alert server would be waiting alert result. wait-timeout: 0 heartbeat-interval: 60s
registry: type: zookeeper zookeeper: namespace: dolphinscheduler connect-string: {{ zookeeper_quorum }} retry-policy: base-sleep-time: 60ms max-sleep: 300ms max-retries: 5 session-timeout: 30s connection-timeout: 9s block-until-connected: 600ms digest: ~
metrics: enabled: true
# Override by profile
--- spring: config: activate: on-profile: mysql datasource: driver-class-name: {{ dolphin_database_config['dolphin_database_driver'] }} url: {{ dolphin_database_config['dolphin_database_url'] }} username: {{ dolphin_database_config['dolphin_database_username'] }} password: {{ dolphin_database_config['dolphin_database_password'] }}
